CREATE FUNCTION hiring_private.hiring_candidate_questions(_application_id uuid) RETURNS TABLE(id uuid,label text,type text,section text,sort_order integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT q.id,coalesce(q.label_override,b.label,''),q.type,q.section,q.sort_order FROM public.applications a JOIN public.job_questions q ON q.job_id=a.job_id LEFT JOIN public.question_bank b ON b.id=q.question_id WHERE a.id=_application_id AND a.candidate_id=auth.uid() ORDER BY q.sort_order $$;
REVOKE ALL ON FUNCTION hiring_private.hiring_candidate_questions(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION hiring_private.hiring_candidate_questions(uuid) TO authenticated;
CREATE FUNCTION public.hiring_candidate_questions(_application_id uuid) RETURNS TABLE(id uuid,label text,type text,section text,sort_order integer) LANGUAGE sql STABLE SET search_path='' AS $$ SELECT * FROM hiring_private.hiring_candidate_questions(_application_id) $$;
REVOKE ALL ON FUNCTION public.hiring_candidate_questions(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.hiring_candidate_questions(uuid) TO authenticated;
CREATE FUNCTION hiring_private.hiring_candidate_contact() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT from_email FROM public.hiring_settings WHERE auth.uid() IS NOT NULL LIMIT 1 $$;
REVOKE ALL ON FUNCTION hiring_private.hiring_candidate_contact() FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION hiring_private.hiring_candidate_contact() TO authenticated;
CREATE FUNCTION public.hiring_candidate_contact() RETURNS text LANGUAGE sql STABLE SET search_path='' AS $$ SELECT hiring_private.hiring_candidate_contact() $$;
REVOKE ALL ON FUNCTION public.hiring_candidate_contact() FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.hiring_candidate_contact() TO authenticated;
CREATE FUNCTION hiring_private.hiring_candidate_email_status(_application_id uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT l.status FROM public.email_log l JOIN public.applications a ON a.id=l.application_id WHERE a.id=_application_id AND a.candidate_id=auth.uid() AND l.trigger_key='application_submitted' ORDER BY l.created_at DESC LIMIT 1 $$;
REVOKE ALL ON FUNCTION hiring_private.hiring_candidate_email_status(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION hiring_private.hiring_candidate_email_status(uuid) TO authenticated;
CREATE FUNCTION public.hiring_candidate_email_status(_application_id uuid) RETURNS text LANGUAGE sql STABLE SET search_path='' AS $$ SELECT hiring_private.hiring_candidate_email_status(_application_id) $$;
REVOKE ALL ON FUNCTION public.hiring_candidate_email_status(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.hiring_candidate_email_status(uuid) TO authenticated;
CREATE FUNCTION hiring_private.hiring_candidate_submit_task(_application_id uuid,_url text,_note text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE e uuid; a public.applications; BEGIN
IF auth.uid() IS NULL OR length(coalesce(_note,''))>500 THEN RAISE EXCEPTION 'Invalid task note'; END IF;
SELECT * INTO a FROM public.applications WHERE id=_application_id AND candidate_id=auth.uid() FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Application ownership required' USING ERRCODE='42501'; END IF;
e:=public.submit_task(_application_id,_url);
IF btrim(coalesce(_note,''))<>'' THEN INSERT INTO public.application_events(application_id,from_status,to_status,message_to_candidate,visible_to_candidate,created_by) VALUES(a.id,a.status_key,a.status_key,'Task note: '||btrim(_note),true,auth.uid()); END IF;RETURN e; END $$;
REVOKE ALL ON FUNCTION hiring_private.hiring_candidate_submit_task(uuid,text,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION hiring_private.hiring_candidate_submit_task(uuid,text,text) TO authenticated;
CREATE FUNCTION public.hiring_candidate_submit_task(_application_id uuid,_url text,_note text DEFAULT '') RETURNS uuid LANGUAGE sql SET search_path='' AS $$ SELECT hiring_private.hiring_candidate_submit_task(_application_id,_url,_note) $$;
REVOKE ALL ON FUNCTION public.hiring_candidate_submit_task(uuid,text,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.hiring_candidate_submit_task(uuid,text,text) TO authenticated;
CREATE POLICY hiring_profile_photo_read_step5 ON storage.objects FOR SELECT TO authenticated USING(bucket_id='task-files' AND name LIKE auth.uid()::text||'/profile/photo-%');